WITH "__duckstream_0" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c8 AS c6, t.c9 AS c7, t.c10 AS c8 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, r.c0 AS c6, r.c1 AS c7, r.c2 AS c8, r.c3 AS c9, r.c4 AS c10 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5 FROM (SELECT "group_id" AS c0, "team_id" AS c1, "add_sub" AS c2, "bias" AS c3 FROM "source_team_group") l LEFT JOIN (SELECT "id" AS c0, "name" AS c1 FROM "source_team") r ON (r.c0 = l.c1)) l LEFT JOIN (SELECT "group_id" AS c0, "team_id" AS c1, "position" AS c2, "points" AS c3, "played" AS c4 FROM "source_standing") r ON ((r.c0 = l.c0) AND (r.c1 = l.c1))) t),
"__duckstream_1" AS (SELECT t.c0 AS c0, t.c1 AS c1 FROM (SELECT t.c0 AS c0, t.c6 AS c1 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, t.c7 AS c7, t.c8 AS c8 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8 FROM "__duckstream_0" v) t WHERE (t.c6 IS NOT NULL)) t) t GROUP BY t.c0, t.c1),
"__duckstream_2" AS (SELECT t.c0 AS c0, CAST(COUNT(*) AS BIGINT) AS c1 FROM (SELECT t.c0 AS c0 FROM (SELECT v.c0 AS c0, v.c1 AS c1 FROM "__duckstream_1" v) t) t GROUP BY t.c0),
"__duckstream_3" AS (SELECT t.c0 AS c0 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6 FROM (SELECT t.c0 AS c0, t.c1 AS c1, CAST(COUNT(t.c2) AS BIGINT) AS c2, CAST(COUNT(*) AS BIGINT) AS c3, CAST(COUNT(t.c3) AS BIGINT) AS c4, CAST(MIN(t.c3) AS INTEGER) AS c5, CAST(MAX(t.c3) AS INTEGER) AS c6 FROM (SELECT t.c0 AS c0, t.c10 AS c1, t.c4 AS c2, t.c6 AS c3 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, l.c6 AS c6, l.c7 AS c7, l.c8 AS c8, r.c0 AS c9, r.c1 AS c10 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8 FROM "__duckstream_0" v) l INNER JOIN (SELECT v.c0 AS c0, v.c1 AS c1 FROM "__duckstream_2" v) r ON (r.c0 = l.c0)) t) t GROUP BY t.c0, t.c1) t WHERE ((t.c2 = t.c3) AND (t.c4 = t.c3) AND (t.c1 = t.c3) AND (t.c5 = CAST(1 AS INTEGER)) AND (CAST(t.c6 AS BIGINT) = t.c3))) t),
"__duckstream_4" AS (SELECT t.c0 AS c0 FROM (SELECT t.c0 AS c0 FROM (SELECT t.c18 AS c0, t.c19 AS c1, t.c20 AS c2, t.c21 AS c3, t.c22 AS c4, t.c23 AS c5, t.c0 AS c6, t.c1 AS c7, t.c2 AS c8, t.c3 AS c9, t.c4 AS c10, t.c5 AS c11, t.c6 AS c12, t.c7 AS c13, t.c8 AS c14, t.c9 AS c15, t.c10 AS c16, t.c11 AS c17, t.c12 AS c18, t.c13 AS c19, t.c14 AS c20, t.c15 AS c21, t.c16 AS c22, t.c17 AS c23 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, l.c6 AS c6, l.c7 AS c7, l.c8 AS c8, l.c9 AS c9, l.c10 AS c10, l.c11 AS c11, l.c12 AS c12, l.c13 AS c13, l.c14 AS c14, l.c15 AS c15, l.c16 AS c16, l.c17 AS c17, r.c0 AS c18, r.c1 AS c19, r.c2 AS c20, r.c3 AS c21, r.c4 AS c22, r.c5 AS c23 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, t.c7 AS c7, t.c8 AS c8, t.c9 AS c9, t.c10 AS c10, t.c11 AS c11, t.c12 AS c12, t.c13 AS c13, t.c14 AS c14, t.c15 AS c15, t.c16 AS c16, t.c17 AS c17 FROM (SELECT "id" AS c0, "phase_id" AS c1, "home_id" AS c2, "away_id" AS c3, "home_field" AS c4, "played" AS c5, "home_score" AS c6, "away_score" AS c7, "moment" AS c8, "withdrawn" AS c9, "home_key_0" AS c10, "home_key_1" AS c11, "home_key_2" AS c12, "home_key_3" AS c13, "away_key_0" AS c14, "away_key_1" AS c15, "away_key_2" AS c16, "away_key_3" AS c17 FROM "source_game") t WHERE ((NOT t.c5) AND (NOT t.c9))) l INNER JOIN (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c0 AS c4, t.c1 AS c5 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5 FROM (SELECT "id" AS c0, "phase_id" AS c1 FROM "source_stage_group") l INNER JOIN (SELECT "group_id" AS c0, "team_id" AS c1, "add_sub" AS c2, "bias" AS c3 FROM "source_team_group") r ON (l.c0 = r.c0)) t) r ON ((l.c1 = r.c5) AND ((r.c1 = l.c2) OR (r.c1 = l.c3)))) t) t) t GROUP BY t.c0),
"__duckstream_5" AS (SELECT t.c0 AS c0, (t.c12 IS NOT NULL) AS c1, t.c5 AS c2, t.c6 AS c3, t.c7 AS c4, t.c9 AS c5, t.c10 AS c6, t.c11 AS c7 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, l.c6 AS c6, l.c7 AS c7, l.c8 AS c8, l.c9 AS c9, l.c10 AS c10, l.c11 AS c11, r.c0 AS c12 FROM (SELECT t.c4 AS c0, t.c5 AS c1, t.c6 AS c2, t.c7 AS c3, t.c8 AS c4, t.c9 AS c5, t.c10 AS c6, t.c11 AS c7, t.c0 AS c8, t.c1 AS c9, t.c2 AS c10, t.c3 AS c11 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8, r.c5 AS c9, r.c6 AS c10, r.c7 AS c11 FROM (SELECT "id" AS c0, "point_win" AS c1, "point_draw" AS c2, "point_loss" AS c3 FROM "source_championship") l INNER JOIN (SELECT t.c5 AS c0, t.c6 AS c1, t.c7 AS c2, t.c0 AS c3, t.c1 AS c4, t.c2 AS c5, t.c3 AS c6, t.c4 AS c7 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, r.c0 AS c5, r.c1 AS c6, r.c2 AS c7 FROM (SELECT "id" AS c0, "championship_id" AS c1, "sort" AS c2, "bonus_points" AS c3, "bonus_points_threshold" AS c4 FROM "source_phase") l INNER JOIN (SELECT t.c1 AS c0, t.c2 AS c1, t.c0 AS c2 FROM (SELECT l.c0 AS c0, r.c0 AS c1, r.c1 AS c2 FROM (SELECT v.c0 AS c0 FROM "__duckstream_3" v) l INNER JOIN (SELECT "id" AS c0, "phase_id" AS c1 FROM "source_stage_group") r ON (l.c0 = r.c0)) t) r ON (l.c0 = r.c1)) t) r ON (l.c0 = r.c4)) t) l LEFT JOIN (SELECT v.c0 AS c0 FROM "__duckstream_4" v) r ON (r.c0 = l.c0)) t)
SELECT CAST(result.c0 AS VARCHAR) AS "id", CAST(result.c1 AS BOOLEAN) AS "live", CAST(result.c2 AS VARCHAR) AS "sort", CAST(result.c3 AS INTEGER) AS "bonus_points", CAST(result.c4 AS INTEGER) AS "bonus_points_threshold", CAST(result.c5 AS INTEGER) AS "win", CAST(result.c6 AS INTEGER) AS "draw", CAST(result.c7 AS INTEGER) AS "loss" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7 FROM "__duckstream_5" v) result;
